import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if webpage_url.startswith("http://") or webpage_url.startswith("https://"):
        try:
            response = requests.get(webpage_url, verify=False)
            response.raise_for_status()
            content = response.content
        except requests.RequestException:
            raise
    else:
        with open(webpage_url, "rb") as f:
            content = f.read()

    tree = html.fromstring(content)
    tables = tree.xpath("//table")

    if not tables:
        return 0

    table_html = html.tostring(tables[0], encoding="unicode")

    try:
        dfs = pd.read_html(table_html)
    except ValueError:
        return 0

    if not dfs:
        return 0

    df = dfs[0]

    if df.empty:
        return 0

    try:
        conn = sqlite3.connect(database_name)
        try:
            df.to_sql("my_table", conn, if_exists="replace", index=False)
        finally:
            conn.close()
    except sqlite3.DatabaseError:
        raise

    return len(df)

import json
import requests
import chardet

API_URL = "http://api.example.com/data"

def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content

    if not content:
        return {}

    encoding = from_encoding
    if encoding is None:
        detection = chardet.detect(content)
        encoding = detection.get("encoding")
        if encoding is None:
            raise ValueError("Unable to detect encoding for non-empty content")

    decoded_content = content.decode(encoding)
    reencoded_content = decoded_content.encode(to_encoding)
    final_content = reencoded_content.decode(to_encoding)

    return json.loads(final_content)

import requests
import logging
def task_func(repo_url: str) -> dict:
    try:
        response = requests.get(repo_url, timeout=10, verify=False)

        if response.status_code == 403:
            remaining = response.headers.get("X-RateLimit-Remaining")
            if remaining == "0" or "rate limit" in response.text.lower():
                raise requests.exceptions.HTTPError(
                    "GitHub API rate limit exceeded.",
                    response=response
                )

        response.raise_for_status()

        try:
            repo_info = response.json()
        except ValueError as e:
            raise requests.exceptions.RequestException(
                f"Invalid JSON response: {e}"
            ) from e

    except requests.exceptions.HTTPError:
        raise
    except requests.exceptions.RequestException:
        raise

    open_issues = repo_info.get("open_issues_count", repo_info.get("open_issues", 0))
    threshold = 100

    if isinstance(open_issues, int) and open_issues > threshold:
        warning = f"Warning: repository has a large number of open issues ({open_issues})."
        print(warning)
        logging.warning(warning)

    return repo_info

