import seaborn as sns
# Constants
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    import matplotlib.pyplot as plt

    if not isinstance(url, str) or not url:
        raise Exception("Invalid URL.")

    try:
        response = requests.get(url, headers=HEADERS, params=parameters, verify=False)
        response.raise_for_status()
        data = json.loads(response.text)
    except Exception as e:
        raise Exception(f"Unable to access or retrieve data from URL: {e}")

    try:
        payload = data
        if isinstance(data, dict):
            for key in ["data", "results", "items", "records"]:
                if key in data and isinstance(data[key], (list, dict)):
                    payload = data[key]
                    break

        df = pd.DataFrame(payload)

        if df.empty:
            raise Exception("Empty data returned from API.")

        numeric_df = df.select_dtypes(include="number")

        if numeric_df.empty:
            raise Exception("No numerical data available for correlation heatmap.")

        corr = numeric_df.corr()

        if corr.empty:
            raise Exception("Invalid numerical data for correlation heatmap.")

        _, ax = plt.subplots()
        sns.heatmap(corr, annot=True, cmap="coolwarm", ax=ax)
        plt.show()

        return df, ax
    except Exception as e:
        raise Exception(f"Invalid data or heatmap generation failed: {e}")

