import unicodedata
import requests

URL = 'https://api.github.com/users/'

def task_func(username):
    response = requests.get(URL + username, verify=False)
    response.raise_for_status()

    data = response.json()

    def normalize(value):
        if isinstance(value, str):
            return unicodedata.normalize("NFKD", value).encode("ascii", "ignore").decode("ascii")
        if isinstance(value, dict):
            return {normalize(k): normalize(v) for k, v in value.items()}
        if isinstance(value, list):
            return [normalize(item) for item in value]
        return value

    return normalize(data)

from flask import Flask
from flask_restful import Resource, Api
import requests
def task_func(api_url, template_folder):
    if not api_url:
        raise ValueError("api_url must be provided.")
    if not template_folder:
        raise ValueError("template_folder must be provided.")

    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)

    class ExternalAPIResource(Resource):
        def get(self):
            try:
                response = requests.get(api_url)
                response.raise_for_status()
                return response.json()
            except requests.RequestException as e:
                return {"error": str(e)}, 500
            except ValueError:
                return {"error": "Invalid JSON response from external API."}, 500

    api.add_resource(ExternalAPIResource, "/", "/api/data")

    return app
